toad_implementation.code_blueprint:
canvas {
  size: 800px 1050px;
  fill: #000000;
  font-family: "Syne, sans-serif";
}

>neonGreen = #39FF14;
>laserPink = #FF007F;
>uvViolet = #7928CA;
>darkBg = #000000;

circle #strobeBackdrop {
  at: center of canvas offset 0px -100px;
  size: 500px;
  fill: alpha(>neonGreen, 0.30);
}

text #raveHeadliner {
  at: top center of canvas offset 0px 64px;
  content: "K R A F T W E R K";
  font-size: 64px;
  font-weight: 900;
  color: >neonGreen;
}

text #raveEventDate {
  at: below #raveHeadliner offset 12px;
  content: "24.10.2026 // 23:00 - OPEN END";
  font-size: 16px;
  font-weight: 700;
  color: >laserPink;
}

rect #bassBox {
  at: center of canvas offset 0px 20px;
  size: 680px 260px;
  fill: #0A0A0A;
  stroke: >neonGreen;
  stroke-width: 4px;
}

text #lineupRow1 {
  at: top center of #bassBox offset 0px 32px;
  content: "DAX J  •  KOBOSIL  •  HECTOR OAKS";
  font-size: 22px;
  font-weight: 800;
  color: #FFFFFF;
}

text #lineupRow2 {
  at: below #lineupRow1 offset 24px;
  content: "ELLEN ALLIEN  •  SOMEDIAC  •  SPFDJ";
  font-size: 20px;
  font-weight: 700;
  color: >laserPink;
}

text #lineupRow3 {
  at: below #lineupRow2 offset 24px;
  content: "LIVE MODULAR SYNTH STAGE // FLOOR B";
  font-size: 13px;
  font-weight: 600;
  color: >neonGreen;
}

text #venueFooter {
  at: bottom center of canvas offset 0px -48px;
  content: "SEKTOR 09 INDUSTRIAL VAULT • BERLIN";
  font-size: 14px;
  font-weight: 700;
  color: #FFFFFF;
}
